from itertools import product

colors = [0, 1]
fixed_assignments = {7: 1, 8: 0, 13: 0, 14: 1}

for attempt in product(colors, repeat=21):
    attempt = list(attempt)
    for i, (k, v) in enumerate(fixed_assignments.items()):
        attempt[k] = v

    # Check for monochromatic red cliques of size 3
    for i in range(7):
        for j in range(i + 1, 7):
            for k in range(j + 1, 7):
                idx_i_j = i * 7 + j - (i + 1)
                idx_i_k = i * 7 + k - (i + 1)
                idx_j_k = j * 7 + k - (j + 1)
                if attempt[idx_i_j] == attempt[idx_i_k] == attempt[idx_j_k] == 0:
                    break
            else:
                continue
            break
        else:
            continue
        break
    else:
        # Check for monochromatic blue cliques of size 4
        for i in range(7):
            for j in range(i + 1, 7):
                for k in range(j + 1, 7):
                    for last in range(k + 1, 7):
                        idx_i_j = i * 7 + j - (i + 1)
                        idx_i_k = i * 7 + k - (i + 1)
                        idx_i_last = i * 7 + last - (i + 1)
                        idx_j_k = j * 7 + k - (j + 1)
                        idx_j_last = j * 7 + last - (j + 1)
                        idx_k_last = k * 7 + last - (k + 1)
                        if (attempt[idx_i_j] == attempt[idx_i_k] == attempt[idx_i_last] ==
                            attempt[idx_j_k] == attempt[idx_j_last] == attempt[idx_k_last] == 1):
                            break
                    else:
                        continue
                    break
                else:
                    continue
                break
            else:
                continue
            break
        else:
            print(attempt)
            break
else:
    print("UNSATISFIABLE")
